def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    h = max(0, int(horizon))
    if h == 0:
        return []
    raw = list(history)
    finite = [float(v) for v in raw if isinstance(v, (int, float)) and math.isfinite(float(v))]
    if not finite:
        return [0.0] * h
    fallback = finite[-1]
    x = []
    for v in raw:
        if isinstance(v, (int, float)) and math.isfinite(float(v)):
            fallback = float(v)
        x.append(fallback)
    n = len(x)
    if n < 4:
        return [finite[-1]] * h
    f = str(frequency).lower()
    candidates = [2, 3, 4, 6, 7, 8, 12, 24, 48, 168]
    if 'day' in f:
        candidates += [5, 7, 14, 28, 30, 365]
    elif 'week' in f:
        candidates += [4, 13, 26, 52]
    elif 'month' in f:
        candidates += [3, 6, 12]
    candidates = sorted(set(p for p in candidates if p < n and n - p >= 3))
    def med(a):
        b = sorted(a)
        m = len(b)
        return b[m // 2] if m % 2 else 0.5 * (b[m // 2 - 1] + b[m // 2])
    start = max(1, n - min(3 * max(candidates or [1]), max(12, n // 3)))
    base_errors = []
    for t in range(start, n):
        w = min(t, max(3, int(round(math.sqrt(t)))))
        pred = med(x[t - w:t]) if w else x[t - 1]
        base_errors.append(abs(x[t] - pred))
    base_score = med(base_errors) if base_errors else float('inf')
    scored = []
    for p in candidates:
        errs = [abs(x[t] - x[t - p]) for t in range(max(p, start), n)]
        if len(errs) >= 3:
            scored.append((med(errs), p))
    if not scored:
        return [med(x[-min(n, 7):])] * h
    score, lag = min(scored)
    if not math.isfinite(score) or score >= base_score:
        return [med(x[-min(n, 7):])] * h
    out = []
    pool = list(x)
    for _ in range(h):
        y = pool[-lag]
        if not math.isfinite(y):
            y = finite[-1]
        out.append(y)
        pool.append(y)
    return out
